import {faultCatalog} from './energy-faults.mjs';
import {createGuidedRepair,guidedChoose,guidedNext,guidedScore} from './repair-guided.mjs';
import {adaptiveExamPlan,examEvidence} from './guided-exam-adaptive.mjs';
export function createGuidedExam(rows,random=Math.random,archive=[]){const id=crypto.randomUUID(),plan=adaptiveExamPlan(examEvidence(rows,archive),random);return {id,date:new Date().toISOString(),status:'active',adaptiveVersion:2,cases:plan.map(p=>{const g=createGuidedRepair(p);g.guidedExam=id;g.adaptation=p.reason;g.examTarget=p.target;g.adaptiveEvidence=p.evidence;return g;})};}
export function guidedExamAct(e,index,action,choice){if(e.status!=='active'||e.cases.findIndex(c=>!c.done)!==index)return false;const g=e.cases[index];if(action==='next'){if(g.phase!=='feedback')return false;guidedNext(g);return true;}if(!['repair','verify'].includes(action))return false;const changed=guidedChoose(g,action,choice);if(e.cases.every(c=>c.done)){e.status='finished';e.finishedAt=new Date().toISOString();}return changed;}
export const guidedExamScore=e=>Math.round(e.cases.reduce((n,c)=>n+guidedScore(c),0)/3);
export function validGuidedExam(e){return e&&typeof e.id==='string'&&['active','finished'].includes(e.status)&&Array.isArray(e.cases)&&e.cases.length===3&&new Set(e.cases.map(c=>c.lab)).size===3&&e.cases.every(c=>faultCatalog[c.lab]&&['basic','combined','intermittent'].includes(c.level)&&['question','feedback'].includes(c.phase)&&Array.isArray(c.faults)&&c.faults.length&&c.faults.every(f=>faultCatalog[c.lab].some(x=>x.id===f))&&['steps','fixed','recommendedIds','hintEvents'].every(k=>Array.isArray(c[k]))&&Number.isFinite(c.errors)&&c.hints===0)&&(e.status!=='finished'||e.cases.every(c=>c.done));}
